    const cutTools=document.createElement("div");cutTools.className="wad2-row";cutTools.innerHTML=`<button data-a="split">${this.t('cut')}</button><button data-a="extract">${this.t('extract')}</button><button data-a="sam3">${this.t('sam3Tag')}</button><button data-a="detect-cuts">${this.lang==='zh'?'检测切镜':'Detect Cuts'}</button><button class="danger" data-a="delete">${this.t('delete')}</button><span class="wad2-muted">${this.lang==='zh'?'过渡 ON 时每段至少 60 帧；OFF 时不限制':'Minimum 60 frames with transition ON; unrestricted when OFF'}</span>`;root.append(cutTools);cutTools.addEventListener("click",e=>{const a=e.target.closest("button")?.dataset.a;if(a)this.action(a)});
